import { MeshPhysicalNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, color, mix, float, vec2, sub, length, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();
  group.name = 'cta-get-started';

  const COLORS = {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const items =
    config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const ctaItem = items.find((i) => i.role === 'headline') ?? items[0];
  const ctaText = ctaItem?.text ?? 'Get started';
  const ctaFontSize = ctaItem?.typography?.fontSize ?? 42;

  const disposables = [];
  const timelines = [];
  const lights = [];

  // ---------- geometry helpers ----------
  function roundedRectShape(w, h, r) {
    const shape = new THREE.Shape();
    const x = -w / 2;
    const y = -h / 2;
    shape.moveTo(x + r, y);
    shape.lineTo(x + w - r, y);
    shape.quadraticCurveTo(x + w, y, x + w, y + r);
    shape.lineTo(x + w, y + h - r);
    shape.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    shape.lineTo(x + r, y + h);
    shape.quadraticCurveTo(x, y + h, x, y + h - r);
    shape.lineTo(x, y + r);
    shape.quadraticCurveTo(x, y, x + r, y);
    return shape;
  }

  const BTN_W = 1.6;
  const BTN_H = 0.5;
  const BTN_R = 0.08;
  const DEPTH = 0.12;

  // ---------- depth plane 1: back halo (grounding / separation) ----------
  const haloGeo = new THREE.CircleGeometry(1.05, 48);
  disposables.push(haloGeo);
  const haloMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  const haloDist = length(sub(uv(), vec2(0.5, 0.5)));
  haloMat.colorNode = color(COLORS.surface);
  haloMat.opacityNode = smoothstep(0.5, 0.0, haloDist).mul(0.45);
  disposables.push(haloMat);
  const halo = new THREE.Mesh(haloGeo, haloMat);
  halo.position.set(0, -0.02, -DEPTH * 1.5);
  group.add(halo);

  // ---------- depth plane 2: machined-metal plate (subject) ----------
  const plateShape = roundedRectShape(BTN_W, BTN_H, BTN_R);
  const plateGeo = new THREE.ExtrudeGeometry(plateShape, {
    depth: DEPTH,
    bevelEnabled: true,
    bevelThickness: 0.02,
    bevelSize: 0.02,
    bevelSegments: 2,
    curveSegments: 8,
  });
  plateGeo.translate(0, 0, -DEPTH / 2);
  disposables.push(plateGeo);

  const plateMat = new MeshPhysicalNodeMaterial({
    color: new THREE.Color(COLORS.ink),
    roughness: 0.55,
    metalness: 0.5,
    clearcoat: 0.2,
    clearcoatRoughness: 0.3,
  });
  disposables.push(plateMat);
  const plate = new THREE.Mesh(plateGeo, plateMat);
  group.add(plate);

  let loadedTex = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTex = tex;
      plateMat.map = tex;
      plateMat.needsUpdate = true;
    });
  }

  // engineered gradient sheen overlay (ink -> surface, subtle grain from metal map underneath)
  const overlayGeo = new THREE.PlaneGeometry(BTN_W * 0.98, BTN_H * 0.98);
  disposables.push(overlayGeo);
  const overlayMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  overlayMat.colorNode = mix(color(COLORS.ink), color(COLORS.surface), uv().y);
  overlayMat.opacityNode = float(0.28);
  disposables.push(overlayMat);
  const overlay = new THREE.Mesh(overlayGeo, overlayMat);
  overlay.position.set(0, 0, DEPTH / 2 + 0.001);
  group.add(overlay);

  // ---------- depth plane 3: accent strip + text (foreground) ----------
  const accentGeo = new THREE.BoxGeometry(BTN_W * 0.5, 0.035, 0.02);
  disposables.push(accentGeo);
  const accentMat = new MeshPhysicalNodeMaterial({
    color: new THREE.Color(COLORS.accent),
    roughness: 0.5,
    metalness: 0.3,
    emissive: new THREE.Color(COLORS.accent),
    emissiveIntensity: 0.6,
  });
  disposables.push(accentMat);
  const accent = new THREE.Mesh(accentGeo, accentMat);
  accent.position.set(0, -BTN_H / 2 + 0.06, DEPTH / 2 + 0.02);
  group.add(accent);

  const textMesh = ctx.fontAtlas.createText(ctaText, {
    fontSize: ctaFontSize,
    color: COLORS.paper,
    align: 'center',
    letterSpacingPx: 1.5,
  });
  textMesh.position.set(0, 0.03, DEPTH / 2 + 0.03);
  group.add(textMesh);

  // ---------- local rim light (accent hue) for metal reflections ----------
  const rim = new THREE.DirectionalLight(new THREE.Color(COLORS.accent), 0.7);
  rim.position.set(-1.2, 0.6, 1.4);
  group.add(rim);
  lights.push(rim);

  const fillKey = new THREE.DirectionalLight(new THREE.Color(COLORS.paper), 0.5);
  fillKey.position.set(1.4, 1.0, 1.6);
  group.add(fillKey);
  lights.push(fillKey);

  // ---------- motion: weighted-settle entrance + one slow idle breathing ----------
  group.scale.setScalar(0.001);
  const entrance = gsap.timeline();
  entrance.to(group.scale, {
    x: 1.04,
    y: 1.04,
    z: 1.04,
    duration: 0.55,
    ease: 'power3.out',
  });
  entrance.to(group.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'power4.out',
  });
  timelines.push(entrance);

  const idle = gsap.timeline({ repeat: -1, yoyo: true, delay: 1.5 });
  idle.to(group.scale, {
    x: 1.015,
    y: 1.015,
    z: 1.015,
    duration: 2.6,
    ease: 'sine.inOut',
  });
  timelines.push(idle);

  // ---------- interaction affordance ----------
  let hoverTween = null;
  let pressTween = null;

  function onPointerOver() {
    hoverTween?.kill();
    hoverTween = gsap.to(group.rotation, {
      x: 0.07,
      duration: 0.3,
      ease: 'power2.out',
    });
  }

  function onPointerOut() {
    hoverTween?.kill();
    hoverTween = gsap.to(group.rotation, {
      x: 0,
      duration: 0.3,
      ease: 'power2.out',
    });
  }

  function onPointerDown() {
    pressTween?.kill();
    pressTween = gsap.to(group.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out(2)',
    });
  }

  function onPointerUp() {
    pressTween?.kill();
    pressTween = gsap.to(group.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.18,
      ease: 'back.out(2)',
    });
  }

  function onClick() {
    ctx.emit('navigate', { to: 'hub-pricing' });
  }

  group.userData.handlers = {
    onPointerOver,
    onPointerOut,
    onPointerDown,
    onPointerUp,
    onClick,
  };

  // ---------- cleanup ----------
  function disposeDeep(obj) {
    obj.traverse((child) => {
      if (child.geometry && !disposables.includes(child.geometry)) {
        child.geometry.dispose();
      }
      if (child.material) {
        const mats = Array.isArray(child.material) ? child.material : [child.material];
        mats.forEach((m) => {
          if (m.map) m.map.dispose();
          if (!disposables.includes(m)) m.dispose();
        });
      }
    });
  }

  group.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    hoverTween?.kill();
    pressTween?.kill();

    disposables.forEach((res) => {
      if (res && typeof res.dispose === 'function') res.dispose();
    });
    if (loadedTex && typeof loadedTex.dispose === 'function') loadedTex.dispose();

    disposeDeep(group);

    lights.forEach((l) => group.remove(l));
    group.clear();
  };

  return group;
}
